/**
 * Progress through an ordered flow (`design/components/stepper.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/stepper.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { mergeProps, onCleanup, onMount, type JSX } from 'solid-js'
import { Dynamic } from 'solid-js/web'

import {
  Each,
  Icon,
  agentMember,
  claimSlot,
  createDerived,
  elementRef,
  scope,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/structure/stepper.module.css'

export type StepperOrientation = NonNullable<StepperProps['orientation']>

export interface Step {
  label: string
  description?: string
  error?: boolean
}

export type StepperSpokenState = 'completed' | 'active' | 'upcoming' | 'error'

export type StepperSpoken = (step: {
  position: number
  count: number
  state: StepperSpokenState
}) => string

export interface StepperProps {
  /**
   * 0-based. Everything before it is completed, everything after it upcoming.
   */
  activeIndex: number
  /**
   * Renders completed steps as buttons. Active and upcoming stay static.
   */
  onStepSelect?: (index: number) => void
  orientation?: 'horizontal' | 'vertical'
  /**
   * Omit for the generic English sentence; localized hosts pass their own.
   */
  spoken?: StepperSpoken
  /**
   * Two to five; the spec says a flow with six steps needs a redesign.
   */
  steps: Step[]
}

/** Progress through an ordered flow. */
export default function Stepper(given: StepperProps): JSX.Element {
  const props = mergeProps(
    {
      orientation: 'horizontal',
      spoken: ({ position, count, state }: Parameters<StepperSpoken>[0]) =>
        `step ${position} of ${count}, ${{ completed: 'completed', active: 'current', upcoming: 'not started', error: 'error' }[state]}`,
    } as Defaults<StepperProps, 'orientation' | 'spoken'>,
    claimSlot(given),
  )
  return scope(() => {
    const root = elementRef<HTMLElement>()
    const rows = createDerived(() =>
      props.steps.map((step, index) =>
        ((walk: 'completed' | 'active' | 'upcoming') => ({
          step,
          index,
          walk,
          state: step.error === true ? ('error' as const) : walk,
        }))(
          index < props.activeIndex
            ? 'completed'
            : index === props.activeIndex
              ? 'active'
              : 'upcoming',
        ),
      ),
    )
    let release1: (() => void) | undefined
    const effect1 = () => {
      release1?.()
      const ran = agentMember({
        member: 'Stepper',
        element: () => root.value,
        state: () => ({
          'active-index': props.activeIndex,
          steps: rows.value.map((row) => ({ label: row.step.label, state: row.state })),
        }),
        actions: {
          set: {
            argument: 'number',
            run: (value) =>
              (() => {
                if (!(props.onStepSelect !== undefined))
                  throw new Error('These steps are not revisitable.')
                if (!Number.isInteger(value) || value < 0 || value >= props.activeIndex) {
                  throw new Error(
                    `Step ${value} is not a completed step, so it cannot be revisited.`,
                  )
                }
                props.onStepSelect?.(value)
              })(),
          },
        },
      })
      release1 = () => {
        ran()
      }
    }
    onMount(effect1)
    onCleanup(() => release1?.())
    return (
      <ol
        class={styles.root}
        data-orientation={props.orientation}
        data-member="stepper"
        ref={root.attach}
      >
        <Each of={rows.value} by={(row) => row.index} renew>
          {(row) => (
            <li
              class={styles.step}
              data-state={row.state}
              data-interactive={
                row.walk === 'completed' && props.onStepSelect !== undefined ? '' : undefined
              }
              aria-current={row.walk === 'active' ? 'step' : undefined}
            >
              {/* control */}
              <Dynamic
                component={
                  row.walk === 'completed' && props.onStepSelect !== undefined ? 'button' : 'span'
                }
                class={styles.control}
                type={
                  row.walk === 'completed' && props.onStepSelect !== undefined
                    ? 'button'
                    : undefined
                }
                onclick={() =>
                  row.walk === 'completed' &&
                  props.onStepSelect !== undefined &&
                  props.onStepSelect?.(row.index)
                }
              >
                {/* indicator */}
                <span class={styles.indicator} aria-hidden="true">
                  {row.state === 'error' ? (
                    <Icon name="error" size="sm" />
                  ) : row.state === 'completed' ? (
                    <span class={styles.check}>
                      <Icon name="confirm" size="sm" />
                    </span>
                  ) : (
                    row.index + 1
                  )}
                </span>
                {/* copy */}
                <span class={styles.copy}>
                  {/* label */}
                  <span class={styles.label}>{row.step.label}</span>
                  {row.step.description !== undefined ? (
                    <span class={styles.description}>{row.step.description}</span>
                  ) : null}
                  {/* spoken */}
                  <span class={styles.spoken}>
                    {`, ${props.spoken({ position: row.index + 1, count: props.steps.length, state: row.state })}`}
                  </span>
                </span>
              </Dynamic>
              {row.index !== props.steps.length - 1 ? (
                <span
                  class={styles.connector}
                  data-filled={row.walk === 'completed' ? '' : undefined}
                />
              ) : null}
            </li>
          )}
        </Each>
      </ol>
    )
  })
}
